design.compositionCss:
/* Electric Type: original widescreen ribbon deck. */
.shell{grid-template-columns:260px minmax(0,1fr)}
.sidebar{padding:28px 18px;border-right:10px solid var(--weekly-mark)}
.brand{padding-bottom:20px;border-bottom:1px solid var(--acid)}
.sidebar nav{display:grid;grid-template-columns:1fr;gap:5px}
.nav-item{min-height:54px;border:1px solid var(--acid);border-left:9px solid var(--weekly-mark);padding:10px 12px;font-family:var(--condensed);font-size:20px;letter-spacing:.01em}
.nav-item span{font-family:var(--body);font-size:10px;min-width:28px}
main{max-width:1700px;padding:0 4vw 78px}
.topbar{min-height:145px;border-bottom:14px solid var(--weekly-mark);padding:28px 0}
.topbar h1{font-family:var(--condensed);font-size:clamp(58px,7vw,100px);line-height:.88;letter-spacing:-.025em;text-transform:uppercase;max-width:980px}
.hero-grid:not(.daily-summary){grid-template-columns:minmax(0,1.7fr) minmax(210px,.55fr);gap:0}
.poster-focus{grid-column:1;grid-row:1/4;min-height:680px;padding:52px 42px;border:0;border-bottom:22px solid var(--weekly-mark)}
.poster-focus h2{font-family:var(--condensed);font-size:clamp(100px,12vw,176px);line-height:.82;letter-spacing:-.02em;text-transform:uppercase;max-width:900px}
.poster-focus h2 span{border-bottom:8px solid var(--weekly-mark);width:fit-content}
.poster-focus .hero-script{font-size:38px!important;max-width:520px}
.poster-focus .cinema-scene{width:55%;right:-8%;top:18%;transform:rotate(-7deg);opacity:.48}
.hero-grid .stat-card{grid-column:2;min-height:0;display:flex;flex-direction:column;align-items:flex-start;border:1px solid var(--ink);border-bottom:9px solid var(--weekly-mark);padding:24px 20px;background:var(--panel)}
.hero-grid .stat-card strong{font-family:var(--condensed);font-size:76px;line-height:.9;margin:10px 0}
.studio-programme{grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border:1px solid var(--ink)}
.studio-programme button{min-height:125px;border:0!important;border-right:1px solid var(--ink)!important;border-bottom:10px solid var(--weekly-mark)!important;padding:22px!important;background:var(--panel)}
.studio-programme span{font-family:var(--condensed);font-size:32px;text-transform:uppercase}
.panel h2,.intro-panel h2,.module h3{font-family:var(--condensed);text-transform:uppercase;letter-spacing:.01em}
.syllabus-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
.module{border:1px solid var(--ink);border-top:12px solid var(--weekly-mark);padding:28px;box-shadow:6px 6px 0 var(--weekly-soft)}
.module h3{font-size:38px}
.roadmap{display:grid;grid-template-columns:1fr;gap:16px;columns:auto}
.phase{min-height:0;margin:0!important;display:grid;grid-template-columns:105px minmax(0,1fr) minmax(0,1fr);gap:24px;align-items:start;border:1px solid var(--ink);border-left:16px solid var(--weekly-mark);padding:26px;background:var(--panel)}
.phase h3{font-family:var(--condensed);font-size:38px;text-transform:uppercase;margin:0}
.phase small{font-family:var(--condensed);font-size:24px;letter-spacing:0}
.resource-list{gap:14px}
.resource{grid-template-columns:minmax(0,1.4fr) minmax(0,1fr) auto;border:1px solid var(--ink);border-bottom:12px solid var(--weekly-mark);padding:24px;box-shadow:none}
.resource h3{font-family:var(--condensed);font-size:26px;text-transform:uppercase}
.evidence-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.evidence-card{border:1px solid var(--ink);border-top:10px solid var(--weekly-mark);padding:24px;box-shadow:4px 4px 0 var(--weekly-soft)}
.cinema-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}
.cinema-film{border:1px solid var(--ink);padding:22px}
.film-cover{min-height:350px;border-bottom:16px solid var(--weekly-mark)}
.cinema-film .film-cover h3{font-family:var(--condensed);font-size:62px;line-height:.9;text-transform:uppercase;letter-spacing:0}
.journal-masthead{border-bottom:14px solid var(--weekly-mark);padding-bottom:34px}
.journal-masthead h2{font-family:var(--condensed);font-size:clamp(94px,12vw,170px);line-height:.82;text-transform:uppercase;letter-spacing:-.025em}
.journal-masthead h2 em{font-family:var(--script);font-size:.72em;text-transform:none}
.journal-workbench{grid-template-columns:minmax(0,1.35fr) minmax(260px,.65fr);gap:26px}
.journal-deck{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.diary-card:nth-child(n){margin:0;transform:none;border:1px solid var(--ink);border-bottom:14px solid var(--weekly-mark);padding:26px;box-shadow:5px 5px 0 var(--weekly-soft)}
.diary-card h3{font-family:var(--condensed);font-size:58px;line-height:.92;text-transform:uppercase;letter-spacing:0}
@media(max-width:1100px) and (min-width:761px){.shell{grid-template-columns:220px minmax(0,1fr)}.poster-focus h2{font-size:105px}.phase{grid-template-columns:90px minmax(0,1fr)}.phase ul{grid-column:2}.evidence-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:760px){.shell{display:block}.sidebar{display:block;border-right:0;border-bottom:9px solid var(--weekly-mark);padding:18px 20px}.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.poster-focus{grid-column:1/-1;grid-row:auto;min-height:530px;padding:30px 22px;border-bottom:14px solid var(--weekly-mark)}.poster-focus h2{font-size:clamp(70px,19vw,104px);line-height:.86}.poster-focus h2 span{border-bottom-width:5px}.poster-focus .hero-script{font-size:27px!important}.poster-focus .cinema-scene{width:72%;right:-15%;opacity:.32}.hero-grid .stat-card{grid-column:auto;min-height:125px;padding:14px 9px;border-bottom-width:6px}.hero-grid .stat-card strong{font-size:39px}.studio-programme{grid-template-columns:1fr;border:0;gap:12px}.studio-programme button{min-height:96px;border:1px solid var(--ink)!important;border-bottom:8px solid var(--weekly-mark)!important}.syllabus-grid,.cinema-grid,.journal-deck,.evidence-grid{grid-template-columns:1fr;gap:18px}.module{padding:22px}.module h3{font-size:31px}.phase{display:block;padding:23px;border-left-width:9px}.phase h3{font-size:32px;margin:12px 0}.resource{display:block;padding:22px}.resource h3{font-size:23px}.film-cover{min-height:300px}.cinema-film .film-cover h3{font-size:46px}.journal-masthead h2{font-size:clamp(64px,18vw,96px)}.journal-workbench{grid-template-columns:1fr}.diary-card:nth-child(n){padding:22px}.diary-card h3{font-size:44px}}
@media(max-width:400px){.topbar h1{font-size:50px}.poster-focus h2{font-size:66px}.hero-grid .stat-card strong{font-size:34px}.journal-masthead h2{font-size:62px}}
